INSERT INTO `blog_posts` (`id`, `title_en`, `title_bn`, `slug`, `content_en`, `content_bn`, `excerpt_en`, `excerpt_bn`, `featured_image`, `user_id`, `category`, `tags`, `status`, `is_featured`, `meta_title`, `meta_description`, `meta_keywords`, `views`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES
(22, 'The Art of Custom Cakes for Every Occasion', 'প্রতিটিক কেক তৈরির উপলক্ষে সাজানোর শিল্প', 'the-art-of-custom-cakes', '<h2>Creating Memories, One Cake at a Time</h2><p>At Saffron Sweets & Bakery, we understand that every celebration is unique. That\'s why we specialize in creating custom cakes that are as special as your moments.</p>\n\n<h3>Our Custom Cake Process</h3>\n<ul>\n<li><strong>Consultation:</strong> We meet with you to understand your vision, preferences, and dietary requirements.</li>\n<li><strong>Design:</strong> Our artists sketch custom designs based on your theme, colors, and preferences.</li>\n<li><strong>Crafting:</strong> Expert bakers create your cake using premium ingredients and traditional techniques.</li>\n<li><strong>Delivery:</strong> Fresh delivery to your venue with proper setup and presentation.</li>\n</ul>\n\n<h3>Popular Custom Cake Designs</h3>\n<ul>\n<li>Wedding Cakes - Multi-tier masterpieces</li>\n<li>Birthday Cakes - Age-appropriate designs</li>\n<li>Anniversary Cakes - Elegant and sophisticated</li>\n<li>Themed Cakes - Your favorite characters and motifs</li>\n<li>Photo Cakes - Edible prints of your cherished memories</li>\n</ul>\n\n<h3>Why Choose Our Custom Cakes?</h3>\n<ul>\n<li>Fresh ingredients sourced locally</li>\n<li>Authentic Bengali sweets expertise since 1995</li>\n<li>Customizable flavors - Vanilla, Chocolate, Mango, Rose, and more</li>\n<li>Dietary options available - Sugar-free, eggless, vegan</li>\n<li>Same-day delivery for urgent orders</li>\n</ul>\n\n<p>Contact us at least 3 days before your event to discuss your custom cake requirements.</p>', '<h2>স্মৃতিটিকের জন্য স্মৃতিটিক কেক</h2><p>সাফ্রন সুইটস এন্ড বেকারিতে, আমরা বুঝতি প্রতিটিটি উপলক্ষের কেক তৈরি করতে পারদর্শক। আমাদের দক্ষ পাকিগুলিরা প্রেম উপাদান দিয়ে প্রতিটিটি স্মৃতিটিক কেক তৈরি করে।</p>', 'Discover how we create stunning custom cakes for birthdays, weddings, and special celebrations. Our expert bakers craft each cake with love and precision.', 'জন্মদিন, বিয়ে এবং বিশেষ উপলক্ষের জন্য আমাদের সুন্দর কাস্টম কেক তৈরি করি। আমাদের দক্ষ পাকিগুলিরা প্রতিটিটিটি এবং যত্নতার সাথে প্রতিটিটি কেক তৈরি করে।', 'blog/custom_cake.png', 1, 'Recipe', 'Custom Cakes, Birthday Cakes, Wedding Cakes, Party Cakes', 'published', 0, 'Custom Cakes for Every Occasion - Saffron Sweets & Bakery', 'Order custom cakes for birthdays, weddings, and special occasions. Expert bakers crafting stunning cakes since 1995.', 'Aut consectetur aliq', 24, '2026-03-24 10:53:13', '2026-03-24 10:53:13', '2026-04-02 07:06:21', NULL),
(23, 'Traditional Biscuits & Custom Cookie Creations', 'ঐতিহ্য বিস্কুট এবং কাস্টম কুকি তৈরি', 'traditional-biscuits-custom-cookies', '<h2>The Art of Bengali Biscuits</h2><p>Bengali biscuits are more than just snacks – they\'re a tradition passed down through generations. At Saffron Sweets & Bakery, we keep this tradition alive while adding modern touches.</p>\n\n<h3>Our Signature Biscuits</h3>\n<ul>\n<li><strong>Naan Khatai:</strong> Buttery, cardamom-infused shortbread cookies that melt in your mouth.</li>\n<li><strong>Shakar Para:</strong> Crispy, sugar-coated biscuits perfect with evening tea.</li>\n<li><strong>Kaju Katli Biscuit:</strong> Cashew goodness in biscuit form – a nut lover\'s dream.</li>\n<li><strong>Badam Pista Biscuit:</strong> Almond and pistachio cookies fit for royalty.</li>\n<li><strong>Coconut Biscuit (Narikoor):</strong> Delicate coconut flakes in a crunchy biscuit.</li>\n</ul>\n\n<h3>Custom Cookie Creations</h3>\n<p>Looking for something unique? Our custom cookies include:</p>\n<ul>\n<li><strong>Photo Cookies:</strong> Edible images on cookies for special events</li>\n<li><strong>Logo Cookies:</strong> Branded cookies for corporate gifting</li>\n<li><strong>Message Cookies:</strong> Cookies with custom messages and names</li>\n<li><strong>Themed Cookies:</strong> Holiday and occasion-specific shapes and designs</li>\n</ul>\n\n<h3>Perfect for Gifting</h3>\n<ul>\n<li>Wedding favors - Customized with couple\'s names</li>\n<li>Corporate gifts - Logo-embossed biscuit boxes</li>\n<li>Birthday parties - Age and theme-specific designs</li>\n<li>Festival treats - Durga Puja, Eid, Diwali specialties</li>\n</ul>\n\n<h3>Freshness Guarantee</h3>\n<ul>\n<li>Baked fresh daily in small batches</li>\nli>Premium quality ingredients - no artificial colors or flavors</li>\nli>Traditional recipes preserved since 1995</li>\n<li>Packaging that maintains freshness for weeks</li>\n</ul>\n\n<p>Contact us to discuss your custom biscuit and cookie requirements. Minimum order quantities apply for custom designs.</p>', '<h2>বাংলার বিস্কুটের ঐতিহ্য</h2><p>বাংলার বিস্কুট শুধু একটি স্ন্যাক নয় – এটি প্রজন্ম প্রজন্ম যায। সাফ্রন সুইটস এন্ড বেকারিতে, আমরা এই ঐতিহ্য বাঁচিয় রাখি আর তাজা আধুনিক ছোঁ যোগ করি।</p>', 'Explore our collection of traditional Bengali biscuits and custom cookie creations. From classic Naan Khatai to modern fusion treats, we bake something for everyone.', 'আমাদের ঐতিহ্য বিস্কুট এবং কাস্টম কুকি সংগ্রহ করুন। ক্লাসিক নান খাতা থেকে আধুনিক ফিউশন ট্রিটস - সবার কিছু না আছে।', 'blog/assorted_biscuits.png', 1, 'Recipe', 'Biscuits, Cookies, Naan Khatai, Custom Sweets, Traditional', 'published', 0, 'Traditional Biscuits & Custom Cookies - Saffron Sweets & Bakery', 'Discover our range of Bengali biscuits and custom cookies. From Naan Khatai to themed cookies for special occasions.', 'Nostrum nisi volupta', 20, '2026-03-24 10:53:25', '2026-03-24 10:53:25', '2026-04-02 10:05:52', NULL),
(28, 'The Authentic Rosogolla Experience', 'প্রামাণিক রসগোল্লার স্বাদ', 'authentic-rosogolla-experience', '<h2>The King of Bengali Sweets</h2><p>When it comes to Bengali sweets, one name stands above all – <strong>Rosogolla</strong>. And not just any rosogolla – we\'re talking about the authentic, spongy rosogolla from Porabari.</p>\n\n<h3>The Legend of Porabari</h3>\n<p>In 1868, Nobin Chandra Das created a revolutionary sweet in the small town of Porabari, West Bengal. Unlike the hard, dry sweets of the time, his rosogolla was soft, spongy, and soaked in sugar syrup. Little did he know that his creation would become the identity of Bengali sweets worldwide.</p>\n\n<h3>What Makes Authentic Rosogolla Special?</h3>\n<ul>\n<li><strong>Texture:</strong> The perfect spongy texture that absorbs syrup but maintains shape</li>\n<li><strong>Sweetness:</strong> Balanced sweetness from pure cane sugar</li>\n<li><strong>Size:</strong> Bite-sized pieces that melt in your mouth</li>\n<li><strong>Freshness:</strong> Made daily, never frozen or stored for long</li>\n<li><strong>Authenticity:</strong> Following the original Porabari recipe</li>\n</ul>\n\n<h3>Our Rosogolla Varieties</h3>\n<ul>\n<li><strong>Classic Spongy Rosogolla:</strong> The traditional favorite</li>\n<li><strong>Gulab Jamun Rosogolla:</strong> A fusion of two classics</li>\n<li><strong>Pista Rosogolla:</strong> Topped with crushed pistachios</li>\n<li><strong>Kesar Rosogolla:</strong> Infused with premium saffron</li>\n<li><strong>Chocolate Rosogolla:</strong> Modern twist on tradition</li>\n<li><strong>Rasmalai Rosogolla:</strong> Soaked in thick, creamy malai</li>\n</ul>\n\n<h3>The Saffron Difference</h3>\n<p>At Saffron Sweets & Bakery, we\'re committed to preserving the authentic taste of Porabari:</p>\n<ul>\n<li>Traditional chana (chickpea flour) base</li>\n<li>Pure ghee for richness</li>\n<li>Natural saffron for color and aroma</li>\n<li>Cardamom for authentic flavor</li>\n<li>No artificial colors or preservatives</li>\n<li>Homemade paneer for filling varieties</li>\n</ul>\n\n<h3>Why the Name \"Rosogolla\"?</h3>\n<p>The name comes from \"Ras\" (juice/syrup) and \"Golla\" (round ball). The sweet round balls floating in sugar syrup literally translates to \"round balls in juice\" – a simple, honest name for an extraordinary sweet.</p>\n\n<h3>Perfect for Every Occasion</h3>\n<ul>\n<li><strong>Puja Offerings:</strong> Traditional offering to Goddess Lakshmi</li>\n<li><strong>Dessert After Meals:</strong> The perfect ending to any feast</li>\n<li><strong>Gift Boxes:</strong> Premium packaging for gifting</li>\n<li><strong>Festival Celebrations:</strong> Durga Puja, Diwali, weddings</li>\n</ul>\n\n<p>Experience the authentic taste of Bengal with our rosogolla. Each piece is a tribute to the rich culinary heritage of our land.</p>', '<h2>বাঙালি মিষ্টিতে রাজা</h2><p>বাঙালি মিষ্টির কথা বলে একটি নাম যার চেয়ে আসে – রসগোল্লা। আর শুধু কোনো রসগোল্লা নয় – আমরা কথা বলছি প্রভারিতামিষ পোরাবাড়ির স্পঞ্জ, নরম ও সত্য রসগোল্লা।</p>', 'Discover the heritage of Bengal\'s most iconic sweet. Learn about the authentic spongy rosogolla from Porabari, its history, and why it\'s called the \"King of Bengali Sweets.\"', 'বাংলার সবচের মিষ টি প্রতীক মিষ্টি - রসগোল্লা। প্রভারিতামিষ রসগোল্লা সম্পর্কে এই মিষ্টি রসগোল্লার উত্তম-ঐতিহ্য এবং ইতিহাস জানুন।', 'blog/rosogolla.png', 1, 'Story', 'Rosogolla, Bengali Sweets, Traditional Sweets, Porabari, Heritage', 'published', 0, 'Authentic Rosogolla - The King of Bengali Sweets', 'Experience the authentic spongy rosogolla from Porabari. Learn about its history, varieties, and why it\'s Bengal\'s favorite sweet.', 'Magnam sit nesciunt', 12, '2026-03-24 11:59:14', '2026-03-24 11:45:23', '2026-04-02 07:14:52', NULL);

